def diff_tapes(old: dict, new: dict) -> List[str]:
    """Pure drift report: how the newly captured behaviour differs from the old
    tape. Empty list = the recording is still true."""
    problems: List[str] = []

    def inbound_events(tape: dict) -> set:
        return {
            f"{entry.get('source')}:{entry.get('event')}"
            for entry in tape.get("timeline", [])
            if entry.get("dir") == "in"
        }

    old_events = inbound_events(old)
    new_events = inbound_events(new)
    for event in sorted(old_events - new_events):
        problems.append(f"no longer seen: {event}")
    for event in sorted(new_events - old_events):
        problems.append(f"new inbound event: {event}")

    old_modules = old.get("mocked_modules", {})
    new_modules = new.get("mocked_modules", {})
    module_names = sorted(set(old_modules) | set(new_modules))

    for module_name in module_names:
        old_methods = old_modules.get(module_name, {}).get("methods", {})
        new_methods = new_modules.get(module_name, {}).get("methods", {})

        for method_name in sorted(set(old_methods) - set(new_methods)):
            problems.append(f"method removed: {module_name}.{method_name}")
        for method_name in sorted(set(new_methods) - set(old_methods)):
            problems.append(f"method added: {module_name}.{method_name}")

        for method_name in sorted(set(old_methods) & set(new_methods)):
            old_method = old_methods[method_name]
            new_method = new_methods[method_name]
            path = f"{module_name}.{method_name}"

            if old_method.get("async") != new_method.get("async"):
                problems.append(
                    f"async behaviour changed: {path} "
                    f"({old_method.get('async')} -> {new_method.get('async')})"
                )

            old_has_return = "return_value" in old_method
            new_has_return = "return_value" in new_method
            old_shape = _shape(old_method["return_value"]) if old_has_return else "<missing>"
            new_shape = _shape(new_method["return_value"]) if new_has_return else "<missing>"
            if old_shape != new_shape:
                problems.append(
                    f"return shape changed: {path} ({old_shape} -> {new_shape})"
                )

    old_schemas = old.get("nested_schemas", {})
    new_schemas = new.get("nested_schemas", {})

    for schema_name in sorted(set(old_schemas) - set(new_schemas)):
        problems.append(f"schema removed: {schema_name}")
    for schema_name in sorted(set(new_schemas) - set(old_schemas)):
        problems.append(f"schema added: {schema_name}")

    for schema_name in sorted(set(old_schemas) & set(new_schemas)):
        old_fields = old_schemas[schema_name]
        new_fields = new_schemas[schema_name]

        added = sorted(set(new_fields) - set(old_fields))
        removed = sorted(set(old_fields) - set(new_fields))
        if added:
            problems.append(f"fields added: {schema_name}: {', '.join(added)}")
        if removed:
            problems.append(f"fields removed: {schema_name}: {', '.join(removed)}")

        for field_name in sorted(set(old_fields) & set(new_fields)):
            if old_fields[field_name] != new_fields[field_name]:
                problems.append(
                    f"field shape changed: {schema_name}.{field_name} "
                    f"({old_fields[field_name]!r} -> {new_fields[field_name]!r})"
                )

    return problems

def render_json(report) -> dict:
    """Lines with their status, findings, and the evidence per test: which tests ran each
    changed line, which noticed its mutant, and what each of those tests fakes. Tools that
    know what a test is *for* (specdeck's requirements) join on the node ids."""

    def value(item):
        return item.value if hasattr(item, "value") else item

    def names(items):
        if items is None:
            return []
        if isinstance(items, str):
            return [items]
        if isinstance(items, dict):
            items = items.keys()
        out = []
        for item in items:
            if isinstance(item, str):
                out.append(item)
            elif hasattr(item, "nodeid"):
                out.append(item.nodeid)
            elif hasattr(item, "name"):
                out.append(item.name)
            else:
                out.append(str(item))
        return sorted(set(out))

    def line_value(mapping, path, line):
        """Get evidence stored either by line or, defensively, by test."""
        if not isinstance(mapping, dict):
            return None
        key = (path, line)
        if key in mapping:
            return mapping[key]
        if path in mapping and isinstance(mapping[path], dict):
            return mapping[path].get(line)
        for test, locations in mapping.items():
            if isinstance(locations, dict):
                locations = locations.keys()
            try:
                if key in locations:
                    return [test]
            except TypeError:
                pass
        return None

    def evidence(path, line, field, alternatives=()):
        for name in (field, *alternatives):
            mapping = getattr(report, name, None)
            found = line_value(mapping, path, line)
            if found is not None:
                return names(found)

        for name in ("evidence", "line_evidence"):
            mapping = getattr(report, name, None)
            item = line_value(mapping, path, line)
            if item is None:
                continue
            if isinstance(item, dict):
                found = item.get(field)
                if found is None:
                    for alternative in alternatives:
                        found = item.get(alternative)
                        if found is not None:
                            break
            else:
                found = getattr(item, field, None)
                if found is None:
                    for alternative in alternatives:
                        found = getattr(item, alternative, None)
                        if found is not None:
                            break
            if found is not None:
                return names(found)
        return []

    def fakes_for(nodeid, tests, fake_maps):
        for mapping in fake_maps:
            if not isinstance(mapping, dict) or nodeid not in mapping:
                continue
            item = mapping[nodeid]
            if isinstance(item, dict) and "fakes" in item:
                item = item["fakes"]
            elif hasattr(item, "fakes"):
                item = item.fakes
            return names(item)

        if isinstance(tests, dict) and nodeid in tests:
            item = tests[nodeid]
            if isinstance(item, dict):
                return names(item.get("fakes", []))
            return names(getattr(item, "fakes", []))
        return []

    lines = []
    test_ids = set()
    for (path, line), status in sorted(report.lines.items()):
        ran_by = evidence(path, line, "ran_by", ("ran", "line_runs", "tests"))
        killed_by = evidence(path, line, "killed_by", ("killed", "kills", "mutant_kills"))
        test_ids.update(ran_by)
        test_ids.update(killed_by)
        lines.append({
            "path": path,
            "line": line,
            "status": value(status),
            "source": report.sources.get((path, line), ""),
            "ran_by": ran_by,
            "killed_by": killed_by,
            "at_import": status == LineStatus.IMPORT_TIME,
        })

    tests = getattr(report, "tests", {})
    if isinstance(tests, dict):
        test_ids.update(tests)
    else:
        for test in tests or []:
            test_ids.add(test if isinstance(test, str) else getattr(test, "nodeid", str(test)))

    fake_maps = [
        getattr(report, name, None)
        for name in ("fakes", "test_fakes", "fakes_by_test", "mocked_by_test")
    ]
    for mapping in fake_maps:
        if isinstance(mapping, dict):
            test_ids.update(mapping)

    test_rows = [
        {"nodeid": nodeid, "fakes": fakes_for(nodeid, tests, fake_maps)}
        for nodeid in sorted(test_ids)
    ]

    findings = []
    for finding in report.findings:
        mutant = finding.mutant
        findings.append({
            "kind": value(finding.kind),
            "path": finding.path,
            "line": finding.line,
            "message": finding.message,
            "snippet": finding.snippet,
            "mutant": None if mutant is None else {
                "original": mutant.original,
                "mutated": mutant.mutated,
            },
        })

    reach = []
    for (path, line), item in sorted(report.reach.items()):
        reach.append({
            "path": path,
            "line": line,
            "function": item["function"],
            "depth": item["depth"],
            "nearest_test": item["nearest_test"],
        })

    return {
        "lines": lines,
        "tests": test_rows,
        "findings": findings,
        "reach": reach,
    }

def is_arid(source: str, line: int) -> bool:
    """True when `line` of `source` should never be mutated."""
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return False

    parents: dict[ast.AST, ast.AST] = {}
    for parent in ast.walk(tree):
        for child in ast.iter_child_nodes(parent):
            parents[child] = parent

    def covers(node: ast.AST) -> bool:
        start = getattr(node, "lineno", None)
        if start is None:
            return False
        return start <= line <= getattr(node, "end_lineno", start)

    for node in ast.walk(tree):
        if not covers(node):
            continue

        if isinstance(node, (ast.Import, ast.ImportFrom)):
            return True

        if isinstance(node, ast.AnnAssign) and node.value is None:
            return True

        if isinstance(node, ast.Expr) and is_docstring(node):
            return True

        if isinstance(node, ast.Call) and _is_noise_call(node):
            return True

        if isinstance(node, ast.stmt) and _in_main_guard(node, parents):
            return True

        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            body_start = node.body[0].lineno if node.body else node.lineno
            if node.lineno <= line <= max(node.lineno, body_start - 1):
                return True

    return False

